import React, { useState, useEffect, useCallback } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  Button,
  CircularProgress,
  Box,
} from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import axios from 'axios';

const ParkingQRCodePage = () => {
  const [slots, setSlots] = useState([]);
  const [loading, setLoading] = useState(true);
  const frontendBaseUrl = `${window.location.origin}/parking`;

  // Fetch parking slots from the API
  const fetchSlots = useCallback(async () => {
    try {
      const res = await axios.get('https://parkingsystem-8xdu.onrender.com/api/lots'); // Update with your actual API
      setSlots(res.data);
    } catch (err) {
      console.error('Error fetching parking slots:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchSlots();
  }, [fetchSlots]);

  // Function to download the QR code as an image
  const downloadQR = useCallback((slotId, slotNumber) => {
    const canvas = document.createElement('canvas');
    const svg = document.getElementById(`qr-${slotId}`);
    const serializer = new XMLSerializer();
    const source = serializer.serializeToString(svg);

    const img = new Image();
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(source);

    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0);

      const a = document.createElement('a');
      a.download = `QR-ParkingSlot-${slotNumber}.png`;
      a.href = canvas.toDataURL('image/png');
      a.click();
    };
  }, []);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Typography variant="h4" component="h1" gutterBottom align="center" color="primary">
        Parking Slot QR Codes
      </Typography>
      <Typography variant="body1" gutterBottom align="center" sx={{ mb: 4 }}>
        Scan QR codes to quickly view parking slot details
      </Typography>

      <Grid container spacing={3}>
        {slots.map((slot) => (
          <Grid item xs={12} sm={6} md={4} key={slot._id}>
            <Card
              sx={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                p: 2,
              }}
              role="region"
              aria-labelledby={`slot-${slot._id}`}
            >
              <CardContent
                sx={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  width: '100%',
                }}
              >
                <QRCodeSVG
                  id={`qr-${slot._id}`}
                  value={`${frontendBaseUrl}/${slot._id}`} // Link to the slot details page
                  size={200}
                  level="H"
                  includeMargin
                  aria-label={`QR code for Parking Slot ${slot.slotNumber}`}
                />
                <Typography
                  variant="h6"
                  component="div"
                  align="center"
                  sx={{ mt: 2, mb: 1 }}
                  id={`slot-${slot._id}`}
                >
                  Slot {slot.slotNumber}
                </Typography>
                <Typography
                  variant="body2"
                  color="text.secondary"
                  align="center"
                  aria-label={`Location: ${slot.location}`}
                >
                  Location: {slot.location}
                </Typography>
                <Typography
                  variant="body2"
                  color="text.secondary"
                  align="center"
                  sx={{ mb: 2 }}
                  aria-label={`Availability: ${slot.isAvailable ? 'Available' : 'Booked'}`}
                >
                  Availability: {slot.isAvailable ? 'Available' : 'Booked'}
                </Typography>
                <Button
                  variant="outlined"
                  startIcon={<DownloadIcon />}
                  onClick={() => downloadQR(slot._id, slot.slotNumber)}
                  size="small"
                  aria-label={`Download QR for Parking Slot ${slot.slotNumber}`}
                >
                  Download QR
                </Button>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Container>
  );
};

export default ParkingQRCodePage;
